res = sys.argv[1]
for i, folder in enumerate(["values", "values-uk", "values-ru"]):
    lines = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    for k, v in S.items():
        text = v[i]
        assert "—" not in text and "–" not in text, k
        text = text.replace("'", "\\'")
        attrs = ' translatable="false"' if (i == 0 and k in ("app_name", "lehko_settings")) else ""
        if i > 0 and k in ("app_name", "lehko_settings"):
            continue
        lines.append(f'    <string name="{k}"{attrs}>{text}</string>')
    lines.append('</resources>')
    os.makedirs(f"{res}/{folder}", exist_ok=True)
    open(f"{res}/{folder}/strings.xml", "w").write("\n".join(lines) + "\n")
print(len(S), "strings")
